    public static List<Question> getQuestionsForTask(int taskId) {
        List<Question> questions = new ArrayList<>();

        switch (taskId) {
            case 7:
                fillTask7(questions);
                break;
            case 12:
                fillTask12(questions);
                break;
            case 13:
                fillTask13(questions);
                break;
            case 14:
                fillTask14(questions);
                break;
        }
        Collections.shuffle(questions);
        return questions;
    }

